// Dray version 313 -> 300 chars
void mainImage( out vec4 o, vec2 U )
{
    float t=iTime;
    vec3 R=iResolution;

    vec2 u =  (U - R.xy/2.)/R.y, s = u;
    u.x -= sin(u.y*sin(t*.1)*10.)*.1;
    u.y -= sin(u.x*sin(t*.12)*14.)*.1;
    u = fract(u*4.)-.5;
    vec4 c = vec4(.5 + .5*cos(t+s.xyx+vec3(0,2,4)), 1)*(1.-abs(.2-length(u))*2.);
    o = mix(c*sin(length(u*20.)-t*3.+vec4(0,2,4,0)), c, c.a);
}
